// Faithful-enough local shim of the Remotion API surface Baz exposes as window.Remotion.
// Used ONLY for free local visual verification. Never uploaded.
import React from 'react';

// ---------- Easing (mirrors remotion/react-native Easing) ----------
const linear = (t) => t;
const ease = bezierFn(0.42, 0, 1, 1);
const quad = (t) => t * t;
const cubic = (t) => t * t * t;
const poly = (n) => (t) => Math.pow(t, n);
const sin = (t) => 1 - Math.cos((t * Math.PI) / 2);
const circle = (t) => 1 - Math.sqrt(1 - t * t);
const exp = (t) => Math.pow(2, 10 * (t - 1));
const back = (s = 1.70158) => (t) => t * t * ((s + 1) * t - s);
const elastic = (bounciness = 1) => {
  const p = bounciness * Math.PI;
  return (t) => 1 - Math.pow(Math.cos((t * Math.PI) / 2), 3) * Math.cos(t * p);
};
function bounce(t) {
  if (t < 1 / 2.75) return 7.5625 * t * t;
  if (t < 2 / 2.75) { t -= 1.5 / 2.75; return 7.5625 * t * t + 0.75; }
  if (t < 2.5 / 2.75) { t -= 2.25 / 2.75; return 7.5625 * t * t + 0.9375; }
  t -= 2.625 / 2.75; return 7.5625 * t * t + 0.984375;
}
function bezierFn(x1, y1, x2, y2) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const sampleX = (t) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t) => ((ay * t + by) * t + cy) * t;
  const sampleDX = (t) => (3 * ax * t + 2 * bx) * t + cx;
  return (x) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const xx = sampleX(t) - x;
      if (Math.abs(xx) < 1e-6) return sampleY(t);
      const d = sampleDX(t);
      if (Math.abs(d) < 1e-6) break;
      t -= xx / d;
    }
    let lo = 0, hi = 1; t = x;
    while (lo < hi) {
      const xx = sampleX(t);
      if (Math.abs(xx - x) < 1e-6) return sampleY(t);
      if (x > xx) lo = t; else hi = t;
      t = (hi - lo) / 2 + lo;
      if (hi - lo < 1e-7) break;
    }
    return sampleY(t);
  };
}
export const Easing = {
  linear, ease, quad, cubic, poly, sin, circle, exp, back, elastic, bounce,
  bezier: bezierFn,
  step0: (n) => (n > 0 ? 1 : 0),
  step1: (n) => (n >= 1 ? 1 : 0),
  in: (e) => e,
  out: (e) => (t) => 1 - e(1 - t),
  inOut: (e) => (t) => (t < 0.5 ? e(t * 2) / 2 : 1 - e((1 - t) * 2) / 2),
};

// ---------- interpolate ----------
export function interpolate(input, inputRange, outputRange, opts = {}) {
  const {
    easing = (t) => t,
    extrapolateLeft = 'extend',
    extrapolateRight = 'extend',
  } = opts;
  if (inputRange.length !== outputRange.length) throw new Error('interpolate range length mismatch');
  let i = 0;
  for (; i < inputRange.length - 2; i++) if (input < inputRange[i + 1]) break;
  const inMin = inputRange[i], inMax = inputRange[i + 1];
  const outMin = outputRange[i], outMax = outputRange[i + 1];
  let t = inMax === inMin ? 0 : (input - inMin) / (inMax - inMin);

  if (input < inputRange[0]) {
    if (extrapolateLeft === 'clamp') return outputRange[0];
    if (extrapolateLeft === 'identity') return input;
  }
  if (input > inputRange[inputRange.length - 1]) {
    if (extrapolateRight === 'clamp') return outputRange[outputRange.length - 1];
    if (extrapolateRight === 'identity') return input;
  }
  t = easing(t);
  return outMin + t * (outMax - outMin);
}

export function interpolateColors(input, inputRange, outputColors) {
  const parse = (c) => {
    if (c.startsWith('#')) {
      let h = c.slice(1);
      if (h.length === 3) h = h.split('').map((x) => x + x).join('');
      return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16), 1];
    }
    const m = c.match(/rgba?\(([^)]+)\)/);
    if (m) { const p = m[1].split(',').map((x) => parseFloat(x)); return [p[0], p[1], p[2], p[3] ?? 1]; }
    return [0, 0, 0, 1];
  };
  const cols = outputColors.map(parse);
  const ch = (k) => interpolate(input, inputRange, cols.map((c) => c[k]), { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  return `rgba(${Math.round(ch(0))}, ${Math.round(ch(1))}, ${Math.round(ch(2))}, ${ch(3)})`;
}

// ---------- spring (analytical damped harmonic oscillator, remotion default) ----------
export function spring({ frame, fps = 30, config = {}, from = 0, to = 1, durationInFrames, delay = 0 }) {
  const { damping = 10, stiffness = 100, mass = 1, overshootClamping = false } = config;
  let t = (frame - delay) / fps;
  if (t < 0) return from;
  if (durationInFrames) {
    // remotion rescales time so the spring settles in durationInFrames
    const natural = springDuration({ damping, stiffness, mass, fps });
    t = t * (natural / (durationInFrames / fps));
  }
  const v0 = 0, x0 = -1; // displacement normalized
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  const omega1 = omega0 * Math.sqrt(1 - zeta * zeta);
  let value;
  if (zeta < 1) {
    const envelope = Math.exp(-zeta * omega0 * t);
    value = -(envelope * (((-v0 + zeta * omega0 * x0) / omega1) * Math.sin(omega1 * t) + x0 * Math.cos(omega1 * t))) + 1;
  } else {
    const envelope = Math.exp(-omega0 * t);
    value = -(envelope * (x0 + (-v0 + omega0 * x0) * t)) + 1;
  }
  if (overshootClamping) value = Math.max(0, Math.min(1, value));
  return from + value * (to - from);
}
function springDuration({ damping, stiffness, mass, fps }) {
  // crude: find first frame where |value-1| < 0.005 for 5 consecutive frames
  let stable = 0;
  for (let f = 0; f < 600; f++) {
    const v = spring({ frame: f, fps, config: { damping, stiffness, mass } });
    if (Math.abs(v - 1) < 0.005) { stable++; if (stable > 5) return (f - 5) / fps; } else stable = 0;
  }
  return 600 / fps;
}

export function random(seed) {
  let s = typeof seed === 'string'
    ? seed.split('').reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0)
    : Math.floor(seed * 100000);
  s = (s ^ 0x5deece66d) & 0xffffffff;
  s = (s * 1103515245 + 12345) & 0x7fffffff;
  return (s % 100000) / 100000;
}

// ---------- Frame context ----------
export const FrameCtx = React.createContext({ frame: 0, width: 1920, height: 1080, fps: 30, durationInFrames: 150 });
export const useCurrentFrame = () => React.useContext(FrameCtx).frame;
export const useVideoConfig = () => {
  const c = React.useContext(FrameCtx);
  return { width: c.width, height: c.height, fps: c.fps, durationInFrames: c.durationInFrames, id: 'main', defaultProps: {}, props: {} };
};

export const AbsoluteFill = React.forwardRef(function AbsoluteFill({ style, children, ...rest }, ref) {
  return React.createElement('div', {
    ref,
    style: {
      position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
      width: '100%', height: '100%', display: 'flex', flexDirection: 'column',
      ...style,
    },
    ...rest,
  }, children);
});

export function Sequence({ from = 0, durationInFrames = Infinity, children, layout, style, name }) {
  const ctx = React.useContext(FrameCtx);
  const local = ctx.frame - from;
  if (local < 0 || local >= durationInFrames) return null;
  const inner = React.createElement(FrameCtx.Provider, { value: { ...ctx, frame: local } }, children);
  if (layout === 'none') return inner;
  return React.createElement(AbsoluteFill, { style }, inner);
}
export const Series = { Sequence };

export const Img = (props) => React.createElement('img', props);
export const Audio = () => null;
export const Video = (props) => videoStill(props);
export const OffthreadVideo = (props) => videoStill(props);
function videoStill({ src, style, muted, startFrom, ...rest }) {
  // Local preview: substitute a poster still so the frame reads correctly offline.
  const poster = globalThis.__VIDEO_POSTER__ || null;
  if (poster) return React.createElement('img', { src: poster, style, ...rest });
  return React.createElement('div', {
    style: { ...style, background: 'linear-gradient(135deg,#3a5a2a,#6b8f4a)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 18, fontFamily: 'monospace' },
  }, 'VIDEO');
}
export const staticFile = (p) => p;
export const continueRender = () => {};
export const delayRender = () => 0;
export const prefetchAsset = () => {};

export function makeRemotion() {
  return {
    AbsoluteFill, Sequence, Series, Img, Audio, Video, OffthreadVideo,
    useCurrentFrame, useVideoConfig, interpolate, interpolateColors, spring,
    Easing, random, staticFile, continueRender, delayRender, prefetchAsset,
  };
}

// Free local scene renderer: transpile scene TSX -> SSR HTML at a given frame -> PNG via playwright.
// Usage: node render.mjs <scene.tsx> <frame> [outPng] [durationInFrames]
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import * as esbuild from 'esbuild';
import { makeRemotion, FrameCtx } from './shim.mjs';

const POSTER = path.resolve(path.dirname(new URL(import.meta.url).pathname), 'mc-poster.png');
if (fs.existsSync(POSTER)) {
  globalThis.__VIDEO_POSTER__ = 'data:image/png;base64,' + fs.readFileSync(POSTER).toString('base64');
}

export async function renderSceneHtml(scenePath, frame, durationInFrames = 150) {
  const src = fs.readFileSync(scenePath, 'utf8');
  const out = esbuild.transformSync(src, {
    loader: 'tsx',
    jsx: 'transform',
    jsxFactory: 'React.createElement',
    jsxFragment: 'React.Fragment',
    format: 'cjs',
    target: 'es2020',
  });
  const module = { exports: {} };
  const sandbox = {
    React,
    module,
    exports: module.exports,
    window: { Remotion: makeRemotion() },
    console,
    Math,
    Date,
    JSON,
    Array,
    Object,
    String,
    Number,
    Boolean,
    require: () => { throw new Error('require() not allowed in scene code'); },
  };
  sandbox.globalThis = sandbox;
  vm.createContext(sandbox);
  vm.runInContext(out.code, sandbox, { filename: scenePath });
  const Comp = module.exports.default || module.exports;
  if (typeof Comp !== 'function') throw new Error('scene has no default-exported component: ' + scenePath);

  const markup = renderToStaticMarkup(
    React.createElement(
      FrameCtx.Provider,
      { value: { frame, width: 1920, height: 1080, fps: 30, durationInFrames } },
      React.createElement(Comp)
    )
  );
  return `<!doctype html><html><head><meta charset="utf-8">
<style>
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;background:#000;width:1920px;height:1080px;overflow:hidden}
  #root{position:relative;width:1920px;height:1080px;overflow:hidden;background:#0a0e1a}
</style></head><body><div id="root">${markup}</div></body></html>`;
}

if (process.argv[1] && process.argv[1].endsWith('render.mjs')) {
  const [scenePath, frameStr, outPng, durStr] = process.argv.slice(2);
  const html = await renderSceneHtml(path.resolve(scenePath), Number(frameStr || 0), Number(durStr || 150));
  const htmlPath = (outPng || '/tmp/scene') + '.html';
  fs.writeFileSync(htmlPath, html);
  if (outPng) {
    const { chromium } = await import('playwright');
    const b = await chromium.launch({ args: ['--no-sandbox', '--font-render-hinting=none'] });
    const p = await b.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
    await p.goto('file://' + htmlPath);
    await p.waitForTimeout(150);
    await p.screenshot({ path: outPng });
    await b.close();
    console.log('wrote ' + outPng);
  } else {
    console.log(htmlPath);
  }
}

