// Free local timeline preview.
//   node preview.mjs sheet <frame,frame,...>   -> renders global frames, builds contact sheets
//   node preview.mjs one <sceneFile> <localFrame> <out.png>
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { renderSceneHtml } from './render.mjs';

const HERE = path.dirname(new URL(import.meta.url).pathname);
const ROOT = path.resolve(HERE, '..');
const OUT = path.join(ROOT, 'out');
fs.mkdirSync(OUT, { recursive: true });

function loadTimeline() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'timeline.json'), 'utf8'));
}

async function shotMany(jobs) {
  const { chromium } = await import('playwright');
  const b = await chromium.launch({ args: ['--no-sandbox', '--font-render-hinting=none'] });
  const p = await b.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
  for (const j of jobs) {
    const html = await renderSceneHtml(j.scenePath, j.localFrame, j.duration);
    const htmlPath = path.join(OUT, '_tmp.html');
    fs.writeFileSync(htmlPath, html);
    await p.goto('file://' + htmlPath);
    await p.waitForTimeout(120);
    await p.screenshot({ path: j.out });
    console.log('  ✓ ' + path.basename(j.out) + '  [' + j.label + ']');
  }
  await b.close();
}

const mode = process.argv[2];

if (mode === 'one') {
  const scenePath = path.resolve(process.argv[3]);
  const localFrame = Number(process.argv[4]);
  const out = path.resolve(process.argv[5]);
  const dur = Number(process.argv[6] || 150);
  await shotMany([{ scenePath, localFrame, duration: dur, out, label: 'single' }]);
} else if (mode === 'sheet') {
  const tl = loadTimeline();
  const frames = process.argv[3].split(',').map(Number);
  const jobs = [];
  for (const gf of frames) {
    const sc = tl.find((s) => gf >= s.start && gf < s.start + s.duration);
    if (!sc) { console.log('  ! no scene at frame ' + gf); continue; }
    jobs.push({
      scenePath: path.join(ROOT, 'scenes', sc.file),
      localFrame: gf - sc.start,
      duration: sc.duration,
      out: path.join(OUT, `f${String(gf).padStart(5, '0')}.png`),
      label: `${gf} · ${sc.name} +${gf - sc.start}`,
    });
  }
  await shotMany(jobs);
  // contact sheets: 6 per sheet, 3 cols
  const files = jobs.map((j) => j.out);
  const per = 6;
  for (let i = 0, n = 0; i < files.length; i += per, n++) {
    const chunk = files.slice(i, i + per);
    const listFile = path.join(OUT, `_sheet${n}.txt`);
    fs.writeFileSync(listFile, chunk.map((f) => `file '${f}'`).join('\n'));
    const outSheet = path.join(OUT, `sheet-${String(n).padStart(2, '0')}.png`);
    const inputs = chunk.flatMap((f) => ['-i', f]);
    const cols = 3, rows = Math.ceil(chunk.length / cols);
    const filter =
      chunk.map((_, k) => `[${k}:v]scale=620:-1,pad=iw+8:ih+8:4:4:0x1a2233[v${k}]`).join(';') +
      ';' +
      chunk.map((_, k) => `[v${k}]`).join('') +
      `xstack=inputs=${chunk.length}:layout=` +
      chunk.map((_, k) => {
        const c = k % cols, r = Math.floor(k / cols);
        return `${c === 0 ? '0' : Array.from({ length: c }, (_, q) => `w${q}`).join('+')}_${r === 0 ? '0' : Array.from({ length: r }, (_, q) => `h${q * cols}`).join('+')}`;
      }).join('|') +
      `[out]`;
    try {
      execFileSync('ffmpeg', ['-y', ...inputs, '-filter_complex', filter, '-map', '[out]', outSheet], { stdio: 'pipe' });
      console.log('sheet -> ' + outSheet + '  frames: ' + chunk.map((f) => path.basename(f, '.png')).join(' '));
    } catch (e) {
      console.log('sheet failed (' + outSheet + '): ' + String(e.stderr || e).slice(-400));
    }
  }
} else {
  console.log('usage: preview.mjs sheet <frames>  |  preview.mjs one <scene> <frame> <out.png> [dur]');
}

