const CL = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' };
const OUT4 = Easing.out(Easing.poly(4));
const OUT3 = Easing.out(Easing.cubic);
const OUT2 = Easing.out(Easing.quad);
const INOUT3 = Easing.inOut(Easing.cubic);

/* Standard entrance: overshoot-settle. Used for artifacts that "arrive". */
function settle(frame, at, fps) {
  return spring({ frame: frame - at, fps: fps, config: { damping: 14, stiffness: 190, mass: 1 } });
}

/* Typewriter — returns the substring visible at this frame. */
function typed(text, frame, start, cps) {
  const n = Math.floor(Math.max(0, frame - start) * (cps / 30));
  return text.slice(0, Math.min(text.length, n));
}
function typeDone(text, start, cps) {
  return start + Math.ceil(text.length / (cps / 30));
}

/* Blinking caret opacity, 16-frame cycle. */
function caret(frame) {
  return frame % 16 < 9 ? 1 : 0.12;
}

/* Animated ellipsis for status lockups: '', '.', '..', '...' */
function ellipsis(frame) {
  return '.'.repeat(Math.floor(frame / 9) % 4);
}

/* ---------------------------------------------------------------------------
   BALLISTIC CURSOR TRAVEL
   11 frames, out(poly(4)). Measured profile across those 11 frames from a
   1020px throw: 1020 -> 140 -> 20 -> 3 -> 0 remaining. Launch fast,
   decelerate hard, then hold dead still. Never linear.
   ------------------------------------------------------------------------ */
function ballistic(frame, start, from, to) {
  const p = interpolate(frame, [start, start + 11], [0, 1], { ...CL, easing: OUT4 });
  return from + (to - from) * p;
}

/* ---------------------------------------------------------------------------
   THE ONE CURSOR — plain arrow, white outline, dark fill. Never swapped.
   Mount inside <Anchor> so x/y are in the operated element's own coordinate
   space and the cursor tracks reflow/scale for free.
   Click legibility = ring-pulse at the tip + a small press-dip. Never a
   different cursor shape.
   ------------------------------------------------------------------------ */
function Anchor({ children }) {
  return <div style={{ position: 'absolute', left: 0, top: 0, width: 0, height: 0 }}>{children}</div>;
}

function Cursor({ x, y, frame, clickAt, opacity }) {
  const has = typeof clickAt === 'number' && clickAt >= 0;
  const since = has ? frame - clickAt : -999;
  const press = since >= 0 && since < 5 ? 0.86 : 1;
  const ringP = interpolate(since, [0, 13], [0, 1], { ...CL, easing: OUT3 });
  const showRing = since >= 0 && since <= 13;
  return (
    <div style={{ position: 'absolute', left: x, top: y, width: 0, height: 0, opacity: opacity, zIndex: 90 }}>
      {showRing ? (
        <div
          style={{
            position: 'absolute',
            left: -30,
            top: -30,
            width: 60,
            height: 60,
            borderRadius: 30,
            border: '2.5px solid rgba(255,255,255,0.9)',
            transform: 'scale(' + (0.28 + ringP * 1.95) + ')',
            opacity: (1 - ringP) * 0.85,
          }}
        />
      ) : null}
      <svg
        width="34"
        height="34"
        viewBox="0 0 24 24"
        style={{ position: 'absolute', left: 0, top: 0, transform: 'scale(' + press + ')', transformOrigin: '0 0' }}
      >
        <path
          d="M1 1 L1 18.4 L5.7 14.1 L8.9 21.2 L12.3 19.6 L9.2 12.8 L15.6 12.4 Z"
          fill="#0b1120"
          stroke="#ffffff"
          strokeWidth="1.6"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
}

/* Full-bleed brand canvas. Every scene sits on this so cuts are seamless. */
function Canvas({ children, dim }) {
