// Assembles each final scene TSX = shared kit(s) verbatim + hand-written scene body.
// Concatenating a single hand-authored kit guarantees byte-identical constants
// across scene boundaries. No AI, no generation.
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.dirname(new URL(import.meta.url).pathname);
const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, 'manifest.json'), 'utf8'));
const kitCache = {};
const kit = (n) => (kitCache[n] ||= fs.readFileSync(path.join(ROOT, 'parts', 'kit-' + n + '.tsx'), 'utf8'));

fs.mkdirSync(path.join(ROOT, 'scenes'), { recursive: true });

let start = 0;
const timeline = [];
for (const s of manifest) {
  const body = fs.readFileSync(path.join(ROOT, 'bodies', s.file), 'utf8');
  const code = ['core', ...(s.kits || [])].map(kit).join('\n') + '\n' + body;
  fs.writeFileSync(path.join(ROOT, 'scenes', s.file), code);
  timeline.push({ file: s.file, name: s.name, start, duration: s.duration, track: 0 });
  start += s.duration;
}
fs.writeFileSync(path.join(ROOT, 'timeline.json'), JSON.stringify(timeline, null, 2));
console.log(manifest.length + ' scenes built · total ' + start + ' frames (' + (start / 30).toFixed(2) + 's)');
for (const t of timeline) console.log(String(t.start).padStart(5) + '  +' + String(t.duration).padStart(3) + '  ' + t.name);

