/* SCENE 02 — cold-open · the morph (54f)
   0-7    pill rect -> card rect. LINEAR over 7 frames, no easing, per spec.
          x/y/w/h/radius and the background colour all shift together.
   0-14   wordmark letters DRAIN left-to-right as the card takes over
   18-29  cursor travels to the input line (11f ballistic) and clicks at 30
   30-54  caret lands, hold */

export default function Scene_coldopen_morph() {
  const frame = useCurrentFrame();

  // LINEAR morph — deliberately un-eased.
  const m = interpolate(frame, [0, 7], [0, 1], CL);
  const bx = PILL_X + (BOX_X - PILL_X) * m;
  const by = PILL_Y + (BOX_Y - PILL_Y) * m;
  const bw = PILL_W + (BOX_W - PILL_W) * m;
  const bh = PILL_H + (BOX_H - PILL_H) * m;
  const br = PILL_R + (BOX_R - PILL_R) * m;

  // background colour shift: translucent pill -> solid card
  const bgR = Math.round(255 + (13 - 255) * m);
  const bgG = Math.round(255 + (21 - 255) * m);
  const bgB = Math.round(255 + (38 - 255) * m);
  const bgA = 0.055 + (0.97 - 0.055) * m;
  const bg = 'rgba(' + bgR + ',' + bgG + ',' + bgB + ',' + bgA + ')';

  // wordmark letters drain left to right
  const drain = function (i) {
    return interpolate(frame, [i * 2, i * 2 + 7], [1, 0], CL);
  };

  // cursor: hold absolute screen position through the morph, then travel to
  // the input line inside the card's coordinate space.
  const holdX = 1002 - bx;
  const holdY = 542 - by;
  const cx = ballistic(frame, 18, holdX, 132);
  const cy = ballistic(frame, 18, holdY, IN_TEXT_Y + 16);

  const barP = interpolate(frame, [8, 18], [0, 1], { ...CL, easing: OUT3 });

  return (
    <Canvas>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Wordmark size={92} tracking={7} color={FG} letterOpacity={drain} />
      </div>

      <Box
        x={bx}
        y={by}
        w={bw}
        h={bh}
        r={br}
        bg={bg}
        borderA={0.09 + 0.03 * m}
        shadow={'0 ' + 30 * m + 'px ' + 90 * m + 'px -30px rgba(0,0,0,0.9)'}
      >
        {/* toolbar rule appears once the card exists */}
        <div
          style={{
            position: 'absolute',
            left: 0,
            top: BAR_Y,
            width: BOX_W,
            height: 1,
            background: 'rgba(255,255,255,0.06)',
            opacity: barP,
          }}
        />
        {/* caret drops in where the cursor clicked */}
        <div
          style={{
            position: 'absolute',
            left: IN_PAD_X,
            top: IN_TEXT_Y,
            width: 2,
            height: 30,
            background: BRAND_400,
            opacity: frame >= 30 ? caret(frame - 30) : 0,
          }}
        />
        <Anchor>
          <Cursor x={cx} y={cy} frame={frame} clickAt={30} opacity={1} />
        </Anchor>
      </Box>
    </Canvas>
  );
}

