/* ---------------------------------------------------------------------------
   STATUS LOCKUP — punctuation between the bigger beats.
   Full-bleed canvas, brand mark + one italic present-tense gerund typing in
   with an animated ellipsis. The pill is sized to the FULL final word up
   front (a hidden sizer span), never to the in-progress typed length, so it
   cannot resize mid-type and clip letters.
   ------------------------------------------------------------------------ */
function StatusLockup({ word, frame, tone }) {
  const full = word + '...';
  const shown = typed(word, frame, 4, 30) + (frame > 4 ? ellipsis(frame - 4) : '');
  const inP = interpolate(frame, [0, 9], [0, 1], { ...CL, easing: OUT4 });
  const c = tone === 'live' ? GREEN : BRAND_400;
  const bg = tone === 'live' ? 'rgba(52,211,153,0.10)' : 'rgba(111,71,245,0.10)';
  const bd = tone === 'live' ? 'rgba(52,211,153,0.28)' : 'rgba(111,71,245,0.30)';
  return (
    <Canvas>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 26,
            padding: '26px 46px',
            borderRadius: 999,
            background: bg,
            border: '1px solid ' + bd,
            opacity: inP,
            transform: 'scale(' + (0.965 + inP * 0.035) + ')',
            boxShadow: '0 30px 80px -40px rgba(111,71,245,0.7)',
          }}
        >
          <Mark size={54} opacity={1} />
          <div style={{ position: 'relative', display: 'inline-block' }}>
            {/* hidden sizer: locks the pill to the full final word */}
            <span
              style={{
                fontFamily: MONO,
                fontStyle: 'italic',
                fontSize: 54,
                fontWeight: 500,
                letterSpacing: -0.5,
                visibility: 'hidden',
                whiteSpace: 'pre',
              }}
            >
              {full}
            </span>
            <span
              style={{
                position: 'absolute',
                left: 0,
                top: 0,
                fontFamily: MONO,
                fontStyle: 'italic',
                fontSize: 54,
                fontWeight: 500,
                letterSpacing: -0.5,
                color: c,
                whiteSpace: 'pre',
              }}
            >
              {shown}
            </span>
          </div>
        </div>
      </div>
    </Canvas>
  );
}

