/* SCENE 07 — generate · context chips pop in (76f)
   The composer is exactly where scene 05 left it. Attachment-style chips pop
   in above the input, one at a time, as the context for the deploy. */

const PROMPT = 'Ubuntu 24.04 · 4 vCPU · 16 GB · 120 GB NVMe';
const CHIPS = [
  ['Plan', 'Max'],
  ['Region', 'Frankfurt · EU-Central'],
  ['Image', 'Ubuntu 24.04'],
  ['Backups', 'Daily'],
];

export default function Scene_generate_chips() {
  const frame = useCurrentFrame();
  const undim = interpolate(frame, [0, 10], [0.72, 0], { ...CL, easing: OUT3 });
  const chipP = function (i) {
    return spring({ frame: frame - (6 + i * 8), fps: 30, config: { damping: 13, stiffness: 220, mass: 1 } });
  };

  return (
    <Canvas dim={undim}>
      <div style={{ position: 'absolute', left: BOX_X, top: BOX_Y - 76, display: 'flex', gap: 14 }}>
        {CHIPS.map(function (c, i) {
          return <Chip key={c[0]} label={c[0]} value={c[1]} p={Math.max(0, chipP(i))} />;
        })}
      </div>

      <Box
