            <span style={{ width: 2, height: 32, background: BRAND_400, marginLeft: 3, opacity: caret(frame) }} />
          </div>
          <div style={{ position: 'absolute', left: IN_PAD_X, top: GLYPH_Y, display: 'flex', gap: 10 }}>
