/* SCENE 09 — generate · the cursor presses Deploy (70f)
   The composer is parked exactly where scene 08 committed it.
   2-13   cursor travels to the Deploy button — 11 frames, ballistic, one
          continuous motion from scene start, never idle-then-jump.
          It is mounted INSIDE the card, so it rides the 0.78 scale for free.
   17     press. Ring pulse at the tip + press dip.
   17-70  the visible consequence, in the same beat: the button commits, a
          progress line sweeps the card, and the artifact brightens. */

const PROMPT = 'Ubuntu 24.04 · 4 vCPU · 16 GB · 120 GB NVMe';
const CHIPS = [
  ['Plan', 'Max'],
  ['Region', 'Frankfurt · EU-Central'],
  ['Image', 'Ubuntu 24.04'],
  ['Backups', 'Daily'],
];
const CLICK = 17;

export default function Scene_generate_send() {
  const frame = useCurrentFrame();

  const scale = 0.78;
  const lift = -340;

  // cursor in the card's own coordinate space -> Deploy button centre
  const cx = ballistic(frame, 2, 150, BTN_X + 72);
  const cy = ballistic(frame, 2, 56, BTN_Y + 25);
  const cOp = interpolate(frame, [CLICK + 12, CLICK + 20], [1, 0], CL);
  const pressed = frame >= CLICK && frame < CLICK + 6;

  const sweep = interpolate(frame, [CLICK, 62], [0, 1], { ...CL, easing: OUT2 });
  const bright = interpolate(frame, [CLICK, 52], [0, 1], { ...CL, easing: OUT3 });
  const artScale = 0.86 + bright * 0.04;

  return (
    <Canvas>
      <div
        style={{
          position: 'absolute',
          left: ART_X,
          top: ART_Y,
          width: ART_W,
          height: ART_H,
          borderRadius: 26,
          border: '1px solid rgba(255,255,255,' + (0.08 + bright * 0.05) + ')',
          background: 'linear-gradient(180deg, rgba(13,21,38,0.96), rgba(6,10,20,0.96))',
          boxShadow: '0 60px 150px -60px rgba(0,0,0,0.95), 0 0 0 ' + bright * 2 + 'px rgba(111,71,245,' + bright * 0.2 + ')',
          transform: 'scale(' + artScale + ')',
          transformOrigin: '50% 100%',
        }}
      >
        <div style={{ position: 'absolute', left: 40, top: 118, width: 1100, height: 8, borderRadius: 4, background: 'rgba(255,255,255,0.07)', overflow: 'hidden' }}>
          <div style={{ width: 26 + sweep * 32 + '%', height: '100%', background: GRAD, borderRadius: 4 }} />
        </div>
      </div>

      <div style={{ position: 'absolute', inset: 0, transform: 'translateY(' + lift + 'px) scale(' + scale + ')', transformOrigin: '960px 540px' }}>
        <div style={{ position: 'absolute', left: BOX_X, top: BOX_Y - 76, display: 'flex', gap: 14 }}>
          {CHIPS.map(function (c) {
            return <Chip key={c[0]} label={c[0]} value={c[1]} p={1} />;
          })}
        </div>

        <Box
          x={BOX_X}
          y={BOX_Y}
          w={BOX_W}
          h={BOX_H}
          r={BOX_R}
          bg={'rgba(13,21,38,0.97)'}
          borderA={0.12}
          shadow={'0 40px 110px -30px rgba(0,0,0,0.95), 0 0 0 3px rgba(111,71,245,0.16)'}
        >
          <div style={{ position: 'absolute', left: 0, top: BAR_Y, width: BOX_W, height: 1, background: 'rgba(255,255,255,0.06)' }} />
          {/* the consequence of the press, on the card itself */}
          <div style={{ position: 'absolute', left: 0, bottom: 0, width: sweep * BOX_W, height: 3, background: GRAD, borderBottomLeftRadius: BOX_R }} />
          <div style={{ position: 'absolute', left: MARK_X, top: MARK_Y }}>
            <Mark size={34} opacity={1} />
          </div>
          <div style={{ position: 'absolute', left: TEXT_X, top: IN_TEXT_Y, display: 'flex', alignItems: 'center', height: 34 }}>
            <span style={{ fontFamily: MONO, fontSize: 28, color: FG, fontWeight: 500, whiteSpace: 'pre', letterSpacing: -0.4 }}>{PROMPT}</span>
            <span style={{ width: 2, height: 32, background: BRAND_400, marginLeft: 3, opacity: frame < CLICK ? caret(frame) : 0 }} />
          </div>
          <div style={{ position: 'absolute', left: IN_PAD_X, top: GLYPH_Y, display: 'flex', gap: 10 }}>
            {GLYPHS.map(function (g) {
              return <ToolGlyph key={g.label} d={g.d} on={1} />;
            })}
          </div>
          <div style={{ position: 'absolute', left: BTN_X, top: BTN_Y }}>
            <DeployButton pressed={pressed} glow={1} />
          </div>

          <Anchor>
            <Cursor x={cx} y={cy} frame={frame} clickAt={CLICK} opacity={cOp} />
          </Anchor>
        </Box>
      </div>
    </Canvas>
  );
}

/* SCENE 10 — generate · the artifact builds (112f)
   0-14    the input card fades and lifts away
   0-16    the artifact takes the frame (0.90 -> 1.00, overshoot-settle)
   6-18    header commits
   12/30/48/66  the four steps ARRIVE IN SEQUENCE — never one finished card
   +10 each     the check strokes on, the row warms
   78-94   the footer identity row lands last
   The progress bar runs the whole scene, so the build has a spine. */

export default function Scene_generate_build() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const fade = interpolate(frame, [0, 14], [1, 0], { ...CL, easing: OUT2 });
  const arrive = settle(frame, 0, fps);
  const artScale = 0.9 + arrive * 0.1;

  const headP = interpolate(frame, [6, 18], [0, 1], { ...CL, easing: OUT4 });
  const prog = interpolate(frame, [4, 92], [0.26, 1], { ...CL, easing: Easing.inOut(Easing.quad) });
  const footP = interpolate(frame, [78, 94], [0, 1], { ...CL, easing: OUT4 });

  const rowP = function (i) {
    return interpolate(frame, [12 + i * 18, 12 + i * 18 + 12], [0, 1], { ...CL, easing: OUT4 });
  };
  const tickP = function (i) {
    return interpolate(frame, [12 + i * 18 + 10, 12 + i * 18 + 20], [0, 1], { ...CL, easing: OUT3 });
  };

  return (
    <Canvas>
      <div
        style={{
          position: 'absolute',
          left: ART_X,
          top: ART_Y,
          width: ART_W,
          height: ART_H,
          borderRadius: 26,
          border: '1px solid rgba(255,255,255,0.13)',
          background: 'linear-gradient(180deg, rgba(13,21,38,0.97), rgba(6,10,20,0.97))',
          boxShadow: '0 60px 150px -60px rgba(0,0,0,0.95), 0 0 0 2px rgba(111,71,245,0.2)',
          transform: 'scale(' + artScale + ')',
          transformOrigin: '50% 100%',
          overflow: 'hidden',
        }}
      >
        {/* header */}
        <div style={{ position: 'absolute', left: 40, top: 34, right: 40, display: 'flex', alignItems: 'center', gap: 20, opacity: headP }}>
          <span style={{ width: 26, height: 26, borderRadius: 13, background: GREEN, display: 'block', boxShadow: '0 0 22px rgba(52,211,153,0.7)' }} />
          <span style={{ fontFamily: SANS, fontSize: 40, fontWeight: 650, color: FG }}>Your server is live</span>
          <span style={{ marginLeft: 'auto', fontFamily: MONO, fontSize: 26, color: CYAN, border: '1px solid rgba(34,211,238,0.34)', borderRadius: 12, padding: '8px 18px' }}>
            47s
          </span>
        </div>

        {/* the spine of the build */}
        <div style={{ position: 'absolute', left: 40, top: 118, width: 1100, height: 8, borderRadius: 4, background: 'rgba(255,255,255,0.07)', overflow: 'hidden' }}>
          <div style={{ width: prog * 100 + '%', height: '100%', background: GRAD, borderRadius: 4 }} />
        </div>

        {/* the steps, arriving one after another */}
        <div style={{ position: 'absolute', left: 40, top: 162, width: 1100 }}>
          {STEPS.map(function (s, i) {
            return <CheckRow key={s[0]} title={s[0]} sub={s[1]} p={rowP(i)} tick={tickP(i)} />;
          })}
        </div>

        {/* identity row, last */}
        <div
          style={{
            position: 'absolute',
            left: 40,
            top: 706,
            width: 1100,
            height: 76,
            borderRadius: 16,
            border: '1px solid rgba(52,211,153,0.16)',
            background: 'rgba(6,20,20,0.4)',
            display: 'flex',
            alignItems: 'center',
            padding: '0 28px',
            gap: 22,
            opacity: footP,
            transform: 'translateY(' + (1 - footP) * 14 + 'px)',
          }}
        >
          <span style={{ fontFamily: MONO, fontSize: 25, color: GREEN, fontWeight: 700 }}>web-prod-01</span>
          <span style={{ fontFamily: SANS, fontSize: 23, color: '#cbd5e1' }}>Frankfurt · EU-Central</span>
          <span style={{ fontFamily: SANS, fontSize: 23, color: MUTED }}>99.9% uptime SLA</span>
          <span style={{ marginLeft: 'auto', fontFamily: MONO, fontSize: 21, color: MUTED, border: '1px solid rgba(255,255,255,0.1)', borderRadius: 9, padding: '7px 14px' }}>
            SSH ready
          </span>
        </div>
      </div>

      {/* the input card, leaving */}
      <div style={{ position: 'absolute', inset: 0, opacity: fade, transform: 'translateY(' + (-340 - (1 - fade) * 60) + 'px) scale(0.78)', transformOrigin: '960px 540px' }}>
        <Box x={BOX_X} y={BOX_Y} w={BOX_W} h={BOX_H} r={BOX_R} bg={'rgba(13,21,38,0.97)'} borderA={0.12} shadow={'0 40px 110px -30px rgba(0,0,0,0.95)'}>
          <div style={{ position: 'absolute', left: 0, top: BAR_Y, width: BOX_W, height: 1, background: 'rgba(255,255,255,0.06)' }} />
          <div style={{ position: 'absolute', left: MARK_X, top: MARK_Y }}>
            <Mark size={34} opacity={1} />
          </div>
          <div style={{ position: 'absolute', left: TEXT_X, top: IN_TEXT_Y, height: 34, display: 'flex', alignItems: 'center' }}>
            <span style={{ fontFamily: MONO, fontSize: 28, color: FG, fontWeight: 500, whiteSpace: 'pre', letterSpacing: -0.4 }}>
              Ubuntu 24.04 · 4 vCPU · 16 GB · 120 GB NVMe
            </span>
          </div>
          <div style={{ position: 'absolute', left: BTN_X, top: BTN_Y }}>
            <DeployButton pressed={false} glow={1} />
          </div>
        </Box>
      </div>
    </Canvas>
  );
}

