    <div style={{ position: 'absolute', left: 30, top: 26, width: CONTENT_W - 60 }}>
      <div style={{ display: 'flex', gap: 20 }}>
        <StatCard label="CPU" value={cpu} unit="%" fill={cpu / 100} p={statP(0)} />
        <StatCard label="MEMORY" value={mem} unit="/16 GB" fill={mem / 16} p={statP(1)} />
        <StatCard label="NETWORK" value={net} unit="Mbps" fill={net / 400} p={statP(2)} />
      </div>

      <div style={{ marginTop: 22 }}>
        <Chart p={chartP} pulse={pulse} />
      </div>

      <div style={{ marginTop: 26, display: 'flex', flexDirection: 'column', gap: 20 }}>
