          <span style={{ fontFamily: SANS, fontSize: 18, color: '#e2e8f0', fontWeight: 550, whiteSpace: 'nowrap' }}>{toast.text}</span>
        </div>
      ) : null}
    </div>
  );
}

/* UPGRADE — the panel the Upgrade tab opens. A single dragged control moves
   between the five real plans; every readout is driven by that one value and
   nothing else on the panel moves. */
function Upgrade({ p, t, dragging, applyP, secs }) {
  const idx = Math.round(t * (PLANS.length - 1));
  const plan = PLANS[idx];
  const TRACK_W = CONTENT_W - 60 - 96;
  return (
    <div style={{ position: 'absolute', left: 30, top: 26, width: CONTENT_W - 60, opacity: p, transform: 'translateY(' + (1 - p) * 18 + 'px)' }}>
      <div style={{ fontFamily: SANS, fontSize: 27, color: FG, fontWeight: 600 }}>Choose your resources</div>
      <div style={{ fontFamily: SANS, fontSize: 18, color: MUTED, marginTop: 7 }}>Resize web-prod-01 without rebuilding it. Billing is prorated.</div>

      {/* the readout — driven only by the dragged value */}
      <div
        style={{
          marginTop: 24,
          borderRadius: 18,
          border: '1px solid rgba(111,71,245,0.32)',
          background: 'rgba(111,71,245,0.09)',
          padding: '24px 28px',
          display: 'flex',
          alignItems: 'center',
          gap: 34,
        }}
      >
        <div style={{ fontFamily: SANS, fontSize: 40, fontWeight: 700, color: FG, width: 190 }}>{plan.n}</div>
        <div style={{ display: 'flex', gap: 30 }}>
          <Spec k="vCPU" v={plan.c} />
          <Spec k="RAM" v={plan.r + ' GB'} />
          <Spec k="NVMe" v={plan.d + ' GB'} />
          <Spec k="Transfer" v={plan.b + ' TB'} />
        </div>
        <div style={{ marginLeft: 'auto', textAlign: 'right' }}>
          <div style={{ fontFamily: MONO, fontSize: 38, fontWeight: 700, color: CYAN, lineHeight: 1 }}>${plan.p}</div>
          <div style={{ fontFamily: SANS, fontSize: 16, color: MUTED, marginTop: 6 }}>per month</div>
        </div>
      </div>

      {/* the track */}
      <div style={{ marginTop: 40, position: 'relative', height: 60, paddingLeft: 48, paddingRight: 48 }}>
        <div style={{ position: 'absolute', left: 48, top: 26, width: TRACK_W, height: 8, borderRadius: 4, background: 'rgba(255,255,255,0.08)' }} />
        <div style={{ position: 'absolute', left: 48, top: 26, width: TRACK_W * t, height: 8, borderRadius: 4, background: GRAD }} />
        {PLANS.map(function (pl, i) {
          const x = 48 + (TRACK_W * i) / (PLANS.length - 1);
          const on = i <= idx;
          return (
            <div key={pl.n} style={{ position: 'absolute', left: x, top: 20, transform: 'translateX(-50%)' }}>
              <div style={{ width: 20, height: 20, borderRadius: 10, background: on ? BRAND_400 : NAVY_600, border: '2px solid ' + (on ? BRAND_400 : 'rgba(255,255,255,0.14)') }} />
              <div style={{ position: 'absolute', left: '50%', top: 30, transform: 'translateX(-50%)', fontFamily: SANS, fontSize: 15, color: i === idx ? FG : MUTED, fontWeight: i === idx ? 650 : 500, whiteSpace: 'nowrap' }}>
                {pl.n}
              </div>
            </div>
          );
        })}
        {/* the handle — follows the cursor 1:1 */}
        <div style={{ position: 'absolute', left: 48 + TRACK_W * t, top: 12, transform: 'translateX(-50%)' }}>
          <div
            style={{
              width: 38,
              height: 38,
              borderRadius: 19,
              background: FG,
              border: '3px solid ' + BRAND_500,
              boxShadow: dragging ? '0 0 0 12px rgba(111,71,245,0.20)' : '0 6px 18px -6px rgba(0,0,0,0.8)',
            }}
          />
        </div>
      </div>

      {/* the apply row */}
      <div style={{ marginTop: 62, display: 'flex', alignItems: 'center', gap: 20 }}>
        <div
          style={{
            padding: '15px 30px',
            borderRadius: 13,
            background: GRAD,
            color: FG,
            fontFamily: SANS,
            fontSize: 19,
            fontWeight: 650,
            transform: 'scale(' + (applyP === 'press' ? 0.96 : 1) + ')',
            boxShadow: '0 12px 34px -12px rgba(111,71,245,0.8)',
          }}
        >
          Apply upgrade
        </div>
        {typeof secs === 'number' ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <span style={{ fontFamily: MONO, fontSize: 32, color: secs === 0 ? GREEN : CYAN, fontWeight: 700 }}>{secs}s</span>
            <span style={{ fontFamily: SANS, fontSize: 18, color: MUTED }}>{secs === 0 ? 'online' : 'until your server is online'}</span>
          </div>
        ) : (
          <span style={{ fontFamily: SANS, fontSize: 18, color: MUTED }}>Your server is 47 seconds away.</span>
        )}
      </div>
    </div>
  );
}

function Spec({ k, v }) {
  return (
    <div>
      <div style={{ fontFamily: SANS, fontSize: 14, letterSpacing: 1.2, color: MUTED, fontWeight: 600 }}>{k}</div>
      <div style={{ fontFamily: MONO, fontSize: 26, color: FG, fontWeight: 600, marginTop: 5 }}>{v}</div>
    </div>
  );
}
