/* SCENE 12 — app-reveal · the chrome assembles (98f)
   Nothing arrives simultaneously. Strict stagger, in the order a person
   would actually perceive the app resolving:
     0-16   window shell + title bar (overshoot-settle)
     18-32  tab bar drops in
     32-46  left rail slides in from the edge
     46-60  content canvas opens
     64-78  floating action toolbar rises last
   Content stays empty here — it populates in scene 13. */

export default function Scene_appreveal_chrome() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const arrive = settle(frame, 0, fps);
  const winScale = 0.94 + arrive * 0.06;
  const winOp = interpolate(frame, [0, 10], [0, 1], { ...CL, easing: OUT3 });

  const chromeP = interpolate(frame, [4, 16], [0, 1], { ...CL, easing: OUT3 });
  const tabsP = interpolate(frame, [18, 32], [0, 1], { ...CL, easing: OUT4 });
  const railP = interpolate(frame, [32, 46], [0, 1], { ...CL, easing: OUT4 });
  const contentP = interpolate(frame, [46, 60], [0, 1], { ...CL, easing: OUT4 });
  const barP = interpolate(frame, [64, 78], [0, 1], { ...CL, easing: OUT4 });

  return (
    <Canvas>
      <Window
        scale={winScale}
        opacity={winOp}
        title="web-prod-01"
        region="Frankfurt · EU-Central"
        status="live"
        statusTone="live"
        chromeP={chromeP}
        showTabs={tabsP}
        showRail={railP}
        showContent={contentP}
        showBar={barP}
        activeTab={0}
        hoverTab={-1}
        bar={<ActionBar p={1} activeIdx={-1} pressIdx={-1} cursorIdx={-1} cursorChild={null} />}
      >
        {/* the canvas opens before it has anything in it — the pieces come next */}
        <div style={{ position: 'absolute', left: 30, top: 26, width: CONTENT_W - 60, opacity: contentP }}>
          <div style={{ fontFamily: SANS, fontSize: 27, color: FG, fontWeight: 600 }}>Overview</div>
          <div style={{ fontFamily: SANS, fontSize: 18, color: MUTED, marginTop: 7 }}>Live metrics for web-prod-01 · 99.9% uptime SLA</div>
        </div>
      </Window>
    </Canvas>
  );
}

/* SCENE 13 — app-reveal · the content canvas populates (80f)
   Chrome is exactly as scene 12 left it and does not move again.
   0/8/16  the three stat cards land one after another
   26-42   the requests chart grows its bars
   44-58   the two capacity meters resolve
   58-80   hold, bars breathing very slightly so the app reads as live */

export default function Scene_appreveal_content() {
  const frame = useCurrentFrame();

  const statP = function (i) {
    return interpolate(frame, [i * 8, i * 8 + 14], [0, 1], { ...CL, easing: OUT4 });
  };
  const chartP = interpolate(frame, [26, 42], [0, 1], { ...CL, easing: OUT4 });
  const meterP = interpolate(frame, [44, 58], [0, 1], { ...CL, easing: OUT4 });

  return (
    <Canvas>
      <Window
        scale={1}
        opacity={1}
        title="web-prod-01"
        region="Frankfurt · EU-Central"
        status="live"
        statusTone="live"
        chromeP={1}
        showTabs={1}
        showRail={1}
        showContent={1}
        showBar={1}
        activeTab={0}
        hoverTab={-1}
        bar={<ActionBar p={1} activeIdx={-1} pressIdx={-1} cursorIdx={-1} cursorChild={null} />}
      >
        <Overview
          statP={statP}
          chartP={chartP}
          meterP={meterP}
          cpu={34}
          mem={2.4}
          memMax={4}
          net={128}
          disk={18}
          diskMax={50}
          bw={0.9}
          bwMax={2}
          pulse={frame}
          toast={null}
        />
      </Window>
    </Canvas>
  );
}

/* SCENE 14 — ui-interaction · the cursor reboots the server (108f)
   The credibility core: a real cursor operating a real control, and every
   click causing a visible consequence in the same beat.
   2-13    ballistic travel, 11 frames, mounted INSIDE the Reboot button so it
           needs no frame coordinates at all
   18      press — ring pulse at the tip, press dip, button commits
   20      CONSEQUENCE: status pill flips live -> rebooting, Reboot becomes the
           active control, CPU collapses and climbs back, a toast confirms
   80      the server comes back and the pill returns to live
   Cursor is gone by 34 — it never lingers after its work is done. */

const CLICK = 18;

export default function Scene_ui_power() {
  const frame = useCurrentFrame();

  const cdx = ballistic(frame, 2, -690, 0);
  const cdy = ballistic(frame, 2, -430, 0);
  const cOp = interpolate(frame, [CLICK + 8, CLICK + 16], [1, 0], CL);

  const rebooting = frame >= 20 && frame < 80;
  const cpu = rebooting
    ? Math.round(interpolate(frame, [20, 34, 62, 80], [34, 4, 9, 41], { ...CL, easing: INOUT3 }))
    : frame < 20
    ? 34
    : 41;
  const net = rebooting ? Math.round(interpolate(frame, [20, 32, 70, 84], [128, 0, 12, 141], CL)) : frame < 20 ? 128 : 141;

  const toast1 = interpolate(frame, [24, 34, 68, 76], [0, 1, 1, 0], CL);
  const toast2 = interpolate(frame, [82, 92], [0, 1], { ...CL, easing: OUT4 });
  const toast = toast2 > 0.02
    ? { p: toast2, text: 'web-prod-01 is back online' }
    : { p: toast1, text: 'Reboot requested · web-prod-01' };

  return (
    <Canvas>
      <Window
        scale={1}
        opacity={1}
        title="web-prod-01"
        region="Frankfurt · EU-Central"
        status={rebooting ? 'rebooting' : 'live'}
        statusTone={rebooting ? 'work' : 'live'}
        chromeP={1}
        showTabs={1}
        showRail={1}
        showContent={1}
        showBar={1}
        activeTab={0}
        hoverTab={-1}
        bar={
          <ActionBar
            p={1}
            activeIdx={rebooting ? 1 : -1}
            pressIdx={frame >= CLICK && frame < CLICK + 6 ? 1 : -1}
            cursorIdx={1}
            cursorChild={<CursorAt dx={cdx} dy={cdy} frame={frame} clickAt={CLICK} opacity={cOp} />}
          />
        }
      >
        <Overview
          statP={function () {
            return 1;
          }}
          chartP={1}
          meterP={1}
          cpu={cpu}
          mem={2.4}
          memMax={4}
          net={net}
          disk={18}
          diskMax={50}
          bw={0.9}
          bwMax={2}
          pulse={rebooting ? 0 : frame}
          toast={toast}
        />
      </Window>
    </Canvas>
  );
}

/* SCENE 16 — ui-interaction · the Upgrade tab is opened (100f)
   2-13   ballistic travel, mounted inside the Upgrade tab itself
   18     press
   19     CONSEQUENCE: the active tab MOVES to Upgrade. The highlight is
          earned by the click — it never just appears.
   19-31  Overview leaves, 28-46 the Upgrade panel arrives
   Cursor gone by 34. */

const CLICK = 18;

export default function Scene_ui_settings() {
  const frame = useCurrentFrame();

  const cdx = ballistic(frame, 2, -430, 322);
  const cdy = ballistic(frame, 2, 336, 0);
  const cOp = interpolate(frame, [CLICK + 8, CLICK + 16], [1, 0], CL);

  const opened = frame >= 19;
  const outP = interpolate(frame, [19, 31], [1, 0], { ...CL, easing: OUT2 });
  const inP = interpolate(frame, [28, 46], [0, 1], { ...CL, easing: OUT4 });

  return (
    <Canvas>
      <Window
        scale={1}
        opacity={1}
        title="web-prod-01"
        region="Frankfurt · EU-Central"
        status="live"
        statusTone="live"
        chromeP={1}
        showTabs={1}
        showRail={1}
        showContent={1}
        showBar={1}
        activeTab={opened ? 8 : 0}
        hoverTab={frame >= 13 && frame < 19 ? 8 : -1}
        cursorTab={8}
        cursorChild={<CursorAt dx={cdx} dy={cdy} frame={frame} clickAt={CLICK} opacity={cOp} />}
        bar={<ActionBar p={1} activeIdx={-1} pressIdx={-1} cursorIdx={-1} cursorChild={null} />}
      >
        <div style={{ position: 'absolute', inset: 0, opacity: outP }}>
          <Overview
            statP={function () {
              return 1;
            }}
            chartP={1}
            meterP={1}
            cpu={41}
            mem={2.4}
            memMax={4}
            net={141}
            disk={18}
            diskMax={50}
            bw={0.9}
            bwMax={2}
            pulse={frame}
            toast={null}
          />
        </div>
        <Upgrade p={inP} t={0.5} dragging={false} applyP={null} secs={null} handleChild={null} applyChild={null} />
      </Window>
    </Canvas>
  );
}

/* SCENE 17 — ui-interaction · the plan is dragged from Standard to Max (98f)
   2-13   ballistic travel to the handle
   18     grab — press dip and ring, the handle takes its active ring
   20-58  the DRAG. The cursor is mounted inside the handle, so the dragged
          value follows the cursor exactly 1:1 by construction.
          Every readout on the panel is derived from that one value; nothing
          else on the panel moves at all — no ambient wobble anywhere.
   60     release
   64-74  the cursor leaves */

const GRAB = 18;

export default function Scene_ui_drag() {
  const frame = useCurrentFrame();

  const cdx = ballistic(frame, 2, -520, 0);
  const cdy = ballistic(frame, 2, 330, 0);
  const cOp = interpolate(frame, [64, 74], [1, 0], CL);

  const t = interpolate(frame, [20, 58], [0.5, 1], { ...CL, easing: INOUT3 });
  const dragging = frame >= GRAB && frame < 60;

  return (
    <Canvas>
      <Window
        scale={1}
        opacity={1}
        title="web-prod-01"
        region="Frankfurt · EU-Central"
        status="live"
        statusTone="live"
        chromeP={1}
        showTabs={1}
        showRail={1}
        showContent={1}
        showBar={1}
        activeTab={8}
        hoverTab={-1}
        cursorTab={-1}
        cursorChild={null}
        bar={<ActionBar p={1} activeIdx={-1} pressIdx={-1} cursorIdx={-1} cursorChild={null} />}
      >
        <Upgrade
          p={1}
          t={t}
          dragging={dragging}
          applyP={null}
          secs={null}
          handleChild={<CursorAt dx={cdx} dy={cdy} frame={frame} clickAt={GRAB} opacity={cOp} />}
          applyChild={null}
        />
      </Window>
    </Canvas>
  );
}

/* SCENE 18 — ui-interaction · 47 seconds, ticking to done (106f)
   The panel is exactly where the drag left it: Max, $32.99.
   2-13    ballistic travel to Apply upgrade
   18      press
   20      CONSEQUENCE: the countdown starts at 47 and the title-bar status
           leaves live for provisioning — the claim is being demonstrated,
           not stated.
   20-86   47 -> 0, with the resize bar tracking it
   88      0s, status returns to live, confirmation lands
   Cursor gone by 32. */

const CLICK = 18;

export default function Scene_ui_timer() {
  const frame = useCurrentFrame();

  const cdx = ballistic(frame, 2, -300, 300);
  const cdy = ballistic(frame, 2, 330, 0);
  const cOp = interpolate(frame, [24, 32], [1, 0], CL);

  const running = frame >= 20;
  const secs = running ? Math.max(0, Math.round(interpolate(frame, [20, 86], [47, 0], { ...CL, easing: Easing.linear }))) : null;
  const prog = interpolate(frame, [20, 86], [0, 1], { ...CL, easing: Easing.linear });
  const done = frame >= 88;
  const doneP = interpolate(frame, [88, 98], [0, 1], { ...CL, easing: OUT4 });

  return (
    <Canvas>
      <Window
        scale={1}
        opacity={1}
        title="web-prod-01"
        region="Frankfurt · EU-Central"
        status={done ? 'live' : running ? 'provisioning' : 'live'}
        statusTone={done ? 'live' : running ? 'work' : 'live'}
        chromeP={1}
        showTabs={1}
        showRail={1}
        showContent={1}
        showBar={1}
        activeTab={8}
        hoverTab={-1}
        cursorTab={-1}
        cursorChild={null}
        bar={<ActionBar p={1} activeIdx={-1} pressIdx={-1} cursorIdx={-1} cursorChild={null} />}
      >
        <Upgrade
          p={1}
          t={1}
          dragging={false}
          applyP={frame >= CLICK && frame < CLICK + 6 ? 'press' : null}
          secs={secs}
          handleChild={null}
          applyChild={<CursorAt dx={cdx} dy={cdy} frame={frame} clickAt={CLICK} opacity={cOp} />}
        />

        {/* the resize running, anchored inside the content canvas */}
        <div style={{ position: 'absolute', left: 30, top: 520, width: CONTENT_W - 60, opacity: running ? 1 : 0 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
            <span style={{ fontFamily: SANS, fontSize: 18, color: '#cbd5e1' }}>Resizing web-prod-01 · 2 vCPU / 4 GB → 4 vCPU / 16 GB</span>
            <span style={{ fontFamily: MONO, fontSize: 17, color: MUTED }}>{Math.round(prog * 100)}%</span>
          </div>
          <div style={{ height: 9, borderRadius: 5, background: 'rgba(255,255,255,0.07)', marginTop: 10, overflow: 'hidden' }}>
            <div style={{ width: prog * 100 + '%', height: '100%', background: GRAD, borderRadius: 5 }} />
          </div>

          <div
            style={{
              marginTop: 26,
              display: 'inline-flex',
              alignItems: 'center',
              gap: 13,
              padding: '14px 24px',
              borderRadius: 13,
              background: 'rgba(6,10,20,0.96)',
              border: '1px solid rgba(52,211,153,0.32)',
              opacity: doneP,
              transform: 'translateY(' + (1 - doneP) * -12 + 'px)',
            }}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={GREEN} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
              <path d="M4 12.5 L9.5 18 L20 6" />
            </svg>
            <span style={{ fontFamily: SANS, fontSize: 19, color: '#e2e8f0', fontWeight: 550 }}>Upgrade applied · web-prod-01 is live on Max</span>
          </div>
        </div>
      </Window>
    </Canvas>
  );
}

/* ============================================================================
   NXEON KIT — MONTAGE WALL
   A drifting grid of tiles showing the breadth of the platform.

   Rules this obeys:
   - HORIZONTAL drift only, one uniform rate. Rows get a fixed x stagger, never
     a different rate, so rows can never converge or overlap.
   - Every tile carries a thin browser-chrome bar so it reads as captured
     software rather than a flat gradient card.
   - 22 distinct tiles across a 12 x 5 = 60 cell grid, indexed with a stride
     of 5 — coprime to both the column count (12) and the pool size (22) — so
     repeats never land in the same row or column.
   - Two cells are pinned: the real gameplay clip and the whip target.
   ========================================================================= */

const TILE_W = 420;
const TILE_H = 252;
const COL_W = 446;
const ROW_H = 278;
const COLS = 12;
const ROWS = 5;
const X0 = -900;
const GRID_TOP = -155;
const SPEED = 5.2;
const STAGGER = [-210, 96, 171, -140, 60];

/* the pinned cells */
const CELL_VIDEO = 30;
const CELL_MATRIX = 31;

const MC_SRC = 'https://media.baz.studio/projects/084d3e8c-2ec8-4a9b-ac1a-96ef5738db08/videos/1787655133275-8f7a6d91-3342-4eb4-8e30-7865d069cd58.mp4';

const POOL = [
  { t: 'Deploy · new server', k: 'wizard', a: BRAND_400 },
  { t: 'web-prod-01 · Overview', k: 'stats', a: BLUE },
  { t: 'Matrix', k: 'panel6', a: BRAND_500 },
  { t: 'you@yourbrand.com', k: 'list', a: BLUE },
  { t: 'One-click WordPress', k: 'grid', a: CYAN },
  { t: 'Free Minecraft server', k: 'console', a: GREEN },
  { t: 'Game servers', k: 'grid', a: BRAND_400 },
  { t: 'survival-smp · live', k: 'video', a: GREEN },
  { t: 'Console · web-prod-01', k: 'console', a: CYAN },
  { t: 'Domains', k: 'list', a: BRAND_400 },
  { t: 'SSL certificates', k: 'list', a: GREEN },
  { t: 'Snapshots', k: 'list', a: BLUE },
  { t: 'Migration Center', k: 'wizard', a: CYAN },
  { t: 'Volumes', k: 'stats', a: BRAND_400 },
  { t: 'Billing', k: 'chart', a: BLUE },
  { t: 'Shared Hosting', k: 'grid', a: BRAND_500 },
  { t: 'Metrics', k: 'chart', a: CYAN },
  { t: 'Networking · Firewall', k: 'list', a: BLUE },
  { t: 'Free tools', k: 'grid', a: BRAND_400 },
  { t: 'Activity', k: 'console', a: MUTED },
  { t: 'Mailboxes', k: 'list', a: BRAND_500 },
  { t: 'rust-01 · running', k: 'stats', a: GREEN },
];

function tileAt(i) {
  if (i === CELL_VIDEO) return POOL[7];
  if (i === CELL_MATRIX) return POOL[2];
  return POOL[(i * 5) % POOL.length];
}

function cellX(i, drift) {
  const col = i % COLS;
  const row = Math.floor(i / COLS);
  return X0 + col * COL_W + STAGGER[row] - drift;
}
function cellY(i) {
  return GRID_TOP + Math.floor(i / COLS) * ROW_H;
}

/* ---- tile interiors. Cheap, but each one is a different real surface ---- */

function MiniBar({ w, c, h }) {
  return <div style={{ width: w, height: h || 7, borderRadius: 4, background: c }} />;
}

function TileBody({ k, a, seed }) {
  const pad = { padding: '14px 16px', height: TILE_H - 30, boxSizing: 'border-box' };
  if (k === 'stats') {
    return (
      <div style={{ ...pad, display: 'flex', flexDirection: 'column', gap: 12 }}>
        <div style={{ display: 'flex', gap: 10 }}>
          {[0, 1, 2].map(function (i) {
            return (
              <div key={i} style={{ flex: 1, border: '1px solid rgba(255,255,255,0.07)', borderRadius: 9, padding: '9px 10px', background: 'rgba(255,255,255,0.02)' }}>
                <MiniBar w={26} c={'rgba(148,163,184,0.5)'} h={5} />
                <div style={{ fontFamily: MONO, fontSize: 21, color: FG, fontWeight: 700, marginTop: 7 }}>{[34, 2.4, 128][i]}</div>
                <div style={{ marginTop: 8 }}>
                  <MiniBar w={[46, 62, 38][i]} c={a} h={5} />
                </div>
              </div>
            );
          })}
        </div>
        <div style={{ flex: 1, border: '1px solid rgba(255,255,255,0.07)', borderRadius: 9, padding: 10, display: 'flex', alignItems: 'flex-end', gap: 5 }}>
          {BARS.map(function (b, i) {
            return <div key={i} style={{ flex: 1, height: b * 74, borderRadius: 3, background: 'linear-gradient(180deg,' + a + ',rgba(59,130,246,0.55))' }} />;
          })}
        </div>
      </div>
    );
  }
  if (k === 'list') {
    return (
      <div style={{ ...pad, display: 'flex', flexDirection: 'column', gap: 9 }}>
        {[0, 1, 2, 3, 4].map(function (i) {
          return (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 11, opacity: 1 - i * 0.11 }}>
              <div style={{ width: 26, height: 26, borderRadius: 13, background: 'rgba(255,255,255,0.07)', border: '1px solid rgba(255,255,255,0.06)' }} />
              <div style={{ flex: 1 }}>
                <MiniBar w={110 + ((seed + i * 37) % 120)} c={'rgba(226,232,240,0.62)'} h={6} />
                <div style={{ marginTop: 6 }}>
                  <MiniBar w={70 + ((seed + i * 53) % 150)} c={'rgba(148,163,184,0.3)'} h={5} />
                </div>
              </div>
              <div style={{ width: 7, height: 7, borderRadius: 4, background: i < 2 ? a : 'rgba(255,255,255,0.09)' }} />
            </div>
          );
        })}
      </div>
    );
  }
  if (k === 'wizard') {
    return (
      <div style={{ ...pad, display: 'flex', flexDirection: 'column', gap: 10 }}>
        {[0, 1, 2, 3].map(function (i) {
          return (
            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 12, border: '1px solid rgba(52,211,153,0.14)', borderRadius: 9, padding: '9px 11px', background: 'rgba(6,20,20,0.35)' }}>
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke={GREEN} strokeWidth="3.2" strokeLinecap="round">
                <path d="M4 12.5 L9.5 18 L20 6" />
              </svg>
              <div style={{ flex: 1 }}>
                <MiniBar w={130 + ((seed + i * 41) % 110)} c={'rgba(226,232,240,0.6)'} h={6} />
              </div>
            </div>
          );
        })}
      </div>
    );
  }
  if (k === 'grid') {
    return (
      <div style={{ ...pad, display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr', gridTemplateRows: '1fr 1fr', gap: 10 }}>
        {[0, 1, 2, 3, 4, 5, 6, 7].map(function (i) {
          return (
            <div key={i} style={{ border: '1px solid rgba(255,255,255,0.07)', borderRadius: 9, background: 'rgba(255,255,255,0.025)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <div style={{ width: 26, height: 26, borderRadius: 7, background: i % 3 === 0 ? a : 'rgba(255,255,255,0.09)', opacity: 0.85 }} />
            </div>
          );
        })}
      </div>
    );
  }
  if (k === 'console') {
    const lines = [62, 148, 96, 178, 120, 84, 156];
    return (
      <div style={{ ...pad, background: 'rgba(0,0,0,0.35)', display: 'flex', flexDirection: 'column', gap: 9, justifyContent: 'flex-start' }}>
        {lines.map(function (w, i) {
          return (
            <div key={i} style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <MiniBar w={16} c={a} h={5} />
              <MiniBar w={w + ((seed + i * 29) % 90)} c={'rgba(148,163,184,0.34)'} h={5} />
            </div>
          );
        })}
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <MiniBar w={9} c={GREEN} h={12} />
        </div>
      </div>
    );
  }
  if (k === 'chart') {
    return (
      <div style={{ ...pad, display: 'flex', alignItems: 'flex-end', gap: 7 }}>
        {BARS.map(function (b, i) {
          return <div key={i} style={{ flex: 1, height: (0.22 + b * 0.78) * 190, borderRadius: 4, background: 'linear-gradient(180deg,' + a + ',rgba(111,71,245,0.4))' }} />;
        })}
      </div>
    );
  }
  if (k === 'panel6') {
    return (
      <div style={{ ...pad, display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gridTemplateRows: '1fr 1fr', gap: 9 }}>
        {[0, 1, 2, 3, 4, 5].map(function (i) {
          return (
            <div key={i} style={{ border: '1px solid rgba(111,71,245,0.3)', borderRadius: 8, background: 'rgba(111,71,245,0.08)', padding: 8, display: 'flex', flexDirection: 'column', gap: 5 }}>
              <MiniBar w={30} c={BRAND_400} h={4} />
              <MiniBar w={54 + ((i * 31) % 34)} c={'rgba(226,232,240,0.4)'} h={4} />
              <MiniBar w={40 + ((i * 47) % 44)} c={'rgba(148,163,184,0.26)'} h={4} />
              <MiniBar w={48 + ((i * 23) % 38)} c={'rgba(148,163,184,0.26)'} h={4} />
            </div>
          );
        })}
      </div>
    );
  }
  return null;
}

/* One tile. The chrome bar is what makes it read as captured software. */
function Tile({ spec, seed, glow }) {
  return (
    <div
      style={{
        width: TILE_W,
        height: TILE_H,
        borderRadius: 14,
        border: '1px solid rgba(255,255,255,' + (0.07 + glow * 0.2) + ')',
        background: 'linear-gradient(180deg, rgba(13,21,38,0.98), rgba(6,10,20,0.98))',
        boxShadow: '0 26px 60px -30px rgba(0,0,0,0.95)' + (glow ? ', 0 0 0 2px rgba(111,71,245,' + glow * 0.5 + ')' : ''),
        overflow: 'hidden',
      }}
    >
      <div style={{ height: 30, display: 'flex', alignItems: 'center', gap: 12, padding: '0 12px', borderBottom: '1px solid rgba(255,255,255,0.055)', background: 'rgba(255,255,255,0.02)' }}>
        <div style={{ display: 'flex', gap: 5 }}>
          <span style={{ width: 7, height: 7, borderRadius: 4, background: '#ff5f57', display: 'block' }} />
          <span style={{ width: 7, height: 7, borderRadius: 4, background: '#febc2e', display: 'block' }} />
          <span style={{ width: 7, height: 7, borderRadius: 4, background: '#28c840', display: 'block' }} />
        </div>
        <span style={{ fontFamily: MONO, fontSize: 12, color: MUTED, whiteSpace: 'nowrap', overflow: 'hidden' }}>{spec.t}</span>
      </div>
      {spec.k === 'video' ? (
        <div style={{ width: TILE_W, height: TILE_H - 30, overflow: 'hidden' }}>
          <OffthreadVideo src={MC_SRC} muted style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </div>
      ) : (
        <TileBody k={spec.k} a={spec.a} seed={seed} />
      )}
    </div>
  );
}

/* The whole wall at a given drift, optionally under a camera whip. */
function Wall({ drift, whip, focusCell }) {
  const cells = [];
  for (let i = 0; i < COLS * ROWS; i++) cells.push(i);
  return (
    <div style={{ position: 'absolute', inset: 0 }}>
      {cells.map(function (i) {
        return (
          <div key={i} style={{ position: 'absolute', left: cellX(i, drift), top: cellY(i) }}>
            <Tile spec={tileAt(i)} seed={i * 17} glow={i === focusCell ? whip : 0} />
          </div>
        );
      })}
    </div>
  );
}

