/* ============================================================================
   NXEON KIT — MATRIX
   Nxeon's AI app builder. Up to six live build consoles side by side, each
   agent shipping a different project in parallel on a server the customer
   owns. This is the artifact-swap beat: it arrives, holds, is edited through
   a real control, and visibly changes on that beat.

   Everything is laid out at a FIXED size and scaled with a CSS transform on
   the wrapper — never by animating width/height/font-size, which would reflow
   and re-wrap the text every frame and read as jitter.
   ========================================================================= */

const MX_X = 140;
const MX_Y = 96;
const MX_W = 1640;
const MX_H = 888;
const MX_TITLE_H = 62;
const MX_BAR_H = 104;
const MX_PAD = 24;
const MX_COL_W = (MX_W - MX_PAD * 2 - 40) / 3;
const MX_ROW_H = (MX_H - MX_TITLE_H - MX_BAR_H - MX_PAD * 2 - 20) / 2;

const CONSOLES = [
  { n: 'bakery-site', s: 'ready' },
  { n: 'orders-api', s: 'building' },
  { n: 'discord-bot', s: 'building' },
  { n: 'landing-v2', s: 'ready' },
  { n: 'admin-portal', s: 'building' },
  { n: 'stripe-hooks', s: 'building' },
];

/* what each console is doing before the edit lands */
const BEFORE = [
  ['npm run build — done', 'caddy: https issued', 'live at bakery.nxeon.app'],
  ['installing postgres@16', 'writing prisma schema', 'seeding order table'],
  ['registering slash commands', 'connecting gateway', 'awaiting token'],
  ['tailwind build — done', 'lighthouse 98 / 100', 'live at landing.nxeon.app'],
  ['scaffolding auth routes', 'wiring session store', 'building role table'],
  ['listening on :4242', 'verifying signature', 'retry queue armed'],
];

/* what the same six consoles do after the request is submitted */
const AFTER = [
  ['+ stripe checkout session', '+ receipt email template', 'redeploying bakery-site'],
  ['+ POST /checkout', '+ webhook secret in env', 'redeploying orders-api'],
  ['+ /order status command', '+ receipt DM on paid', 'redeploying discord-bot'],
  ['+ pricing block', '+ checkout CTA wired', 'redeploying landing-v2'],
  ['+ payments dashboard', '+ refund action', 'redeploying admin-portal'],
  ['+ checkout.completed', '+ invoice.paid', 'redeploying stripe-hooks'],
];

function ConsolePanel({ i, lines, status, p, prog, swap, focus }) {
  const on = status === 'ready';
  return (
    <div
      style={{
        width: MX_COL_W,
        height: MX_ROW_H,
        borderRadius: 16,
        border: '1px solid ' + (focus ? 'rgba(111,71,245,0.55)' : 'rgba(111,71,245,0.26)'),
        background: 'linear-gradient(180deg, rgba(23,17,54,0.75), rgba(10,12,28,0.85))',
        boxSizing: 'border-box',
        padding: '16px 18px',
        opacity: p,
        transform: 'translateY(' + (1 - p) * 16 + 'px)',
        overflow: 'hidden',
        position: 'relative',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 11 }}>
        <span style={{ width: 9, height: 9, borderRadius: 5, background: on ? GREEN : BRAND_400, display: 'block' }} />
        <span style={{ fontFamily: MONO, fontSize: 19, color: FG, fontWeight: 600 }}>{i + 1}. {CONSOLES[i].n}</span>
        <span style={{ marginLeft: 'auto', fontFamily: SANS, fontSize: 14, color: on ? GREEN : BRAND_400, fontWeight: 600 }}>{status}</span>
      </div>

      <div style={{ height: 5, borderRadius: 3, background: 'rgba(255,255,255,0.07)', marginTop: 13, overflow: 'hidden' }}>
        <div style={{ width: prog * 100 + '%', height: '100%', background: GRAD, borderRadius: 3 }} />
      </div>

      <div style={{ marginTop: 16, display: 'flex', flexDirection: 'column', gap: 11 }}>
        {lines.map(function (l, j) {
          const sp = swap ? interpolate(swap, [j * 0.18, j * 0.18 + 0.4], [0, 1], CL) : 1;
          return (
            <div
              key={j}
              style={{
                fontFamily: MONO,
                fontSize: 16,
                color: l.charAt(0) === '+' ? CYAN : MUTED,
                whiteSpace: 'nowrap',
                opacity: sp,
                transform: 'translateX(' + (1 - sp) * 22 + 'px)',
              }}
            >
              {l}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* The Matrix window. `scale` is a transform on the wrapper; the layout inside
   never changes size, so nothing reflows. */
function MatrixWindow({ scale, opacity, panelP, prog, swap, lines, statuses, barP, barChildren, focus, originX, originY }) {
  return (
    <div
      style={{
        position: 'absolute',
        left: MX_X,
        top: MX_Y,
        width: MX_W,
        height: MX_H,
        borderRadius: 22,
        border: '1px solid rgba(255,255,255,0.09)',
        background: 'linear-gradient(180deg, rgba(13,21,38,0.98), rgba(6,10,20,0.98))',
        boxShadow: '0 60px 150px -50px rgba(0,0,0,0.95), 0 0 0 1px rgba(111,71,245,0.1)',
        transform: 'scale(' + scale + ')',
        transformOrigin: (typeof originX === 'number' ? originX + 'px ' + originY + 'px' : '50% 50%'),
        opacity: opacity,
        overflow: 'hidden',
      }}
    >
