/* SCENE 28 — handoff · the ship-it menu cascades open (98f)
   4-28   the menu opens ITEM BY ITEM — each row pops (scale + lift), never a
          fade of the whole panel
   30-41  the cursor arrives on the first row
   46-86  it WALKS the list, snapping row to row in short 6-frame throws; the
          hover state follows it, so every highlight is earned
   86     it clicks Copy SSH command, which motivates the cut to scene 29
   Behind the menu the console keeps working — its output cross-fades through
   three variants so the app stays alive without stealing the beat. */

const MENU = [
  ['Connect a domain', 'M12 3 a9 9 0 1 0 0.1 0 M3 12 h18 M12 3 c4 4 4 14 0 18 c-4 -4 -4 -14 0 -18'],
  ['Add SSL certificate', 'M6 11 V8 a6 6 0 0 1 12 0 v3 M5 11 h14 v9 H5 Z'],
  ['Open in Console', 'M4 5 h16 v14 H4 Z M7 10 l3 2.5 l-3 2.5 M13 15 h4'],
  ['Invite your team', 'M9 11 a4 4 0 1 0 0 -8 a4 4 0 0 0 0 8 M2 21 c0 -4 3.4 -6.5 7 -6.5 s7 2.5 7 6.5 M17 8 h5 M19.5 5.5 v5'],
  ['Download a backup', 'M12 3 v12 M7.5 10.5 L12 15 l4.5 -4.5 M4 19 h16'],
  ['Copy SSH command', 'M9 9 h11 v11 H9 Z M4 15 V4 h11'],
];

const ROW_Y = [0, 74, 148, 222, 296, 370];
const STOPS = [30, 46, 56, 66, 76, 84];
const CLICK = 88;

/* the console output ticking over behind the menu */
const VARIANTS = [
  ['+ stripe checkout session', '+ receipt email template', 'redeploying bakery-site', 'caddy: reloading config'],
  ['build 3.1s — 0 errors', 'uploading 42 assets', 'invalidating edge cache', 'health check: 200 OK'],
  ['certificate renewed', 'https://bakery.nxeon.app', 'all six consoles green', 'ready'],
];

export default function Scene_handoff_menu() {
  const frame = useCurrentFrame();

  // which row the cursor is resting on right now
  let stop = 0;
  for (let i = 0; i < STOPS.length; i++) if (frame >= STOPS[i]) stop = i;
  const prevY = ROW_Y[Math.max(0, stop - 1)];
  const cy = stop === 0 ? ballistic(frame, 30, -430, 0) : interpolate(frame, [STOPS[stop], STOPS[stop] + 6], [prevY - ROW_Y[stop], 0], { ...CL, easing: OUT4 });
  const cx = stop === 0 ? ballistic(frame, 30, -620, 0) : 0;
  const cOp = interpolate(frame, [28, 32, CLICK + 12, CLICK + 20], [0, 1, 1, 0], CL);
  const hover = frame >= 30 ? stop : -1;

  const vIdx = frame >= 72 ? 2 : frame >= 40 ? 1 : 0;
  const vFade = interpolate(frame % 32, [0, 8], [0.55, 1], CL);

  return (
    <Canvas>
      {/* the console detail view we pushed into, still working */}
      <div
        style={{
          position: 'absolute',
          left: 118,
          top: 214,
          width: 900,
          height: 652,
          borderRadius: 20,
          border: '1px solid rgba(111,71,245,0.34)',
          background: 'linear-gradient(180deg, rgba(23,17,54,0.8), rgba(10,12,28,0.92))',
          boxShadow: '0 50px 130px -50px rgba(0,0,0,0.95)',
          padding: '26px 30px',
          boxSizing: 'border-box',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
          <span style={{ width: 12, height: 12, borderRadius: 6, background: BRAND_400, display: 'block' }} />
          <span style={{ fontFamily: MONO, fontSize: 28, color: FG, fontWeight: 600 }}>1. bakery-site</span>
          <span style={{ marginLeft: 'auto' }}>
            <Pill text="building" tone="brand" />
          </span>
        </div>
        <div style={{ height: 7, borderRadius: 4, background: 'rgba(255,255,255,0.07)', marginTop: 20, overflow: 'hidden' }}>
          <div style={{ width: interpolate(frame, [0, 98], [58, 96], CL) + '%', height: '100%', background: GRAD, borderRadius: 4 }} />
        </div>
        <div style={{ marginTop: 28, display: 'flex', flexDirection: 'column', gap: 18, opacity: vFade }}>
          {VARIANTS[vIdx].map(function (l, i) {
            return (
              <div key={l} style={{ fontFamily: MONO, fontSize: 23, color: l.charAt(0) === '+' ? CYAN : MUTED }}>
                {l}
              </div>
            );
          })}
        </div>
      </div>

      {/* the menu */}
      <div
        style={{
          position: 'absolute',
          left: 1090,
          top: 262,
          width: 660,
          padding: 18,
          borderRadius: 20,
          border: '1px solid rgba(255,255,255,0.09)',
          background: 'rgba(6,10,20,0.97)',
          boxShadow: '0 50px 130px -40px rgba(0,0,0,0.95)',
          boxSizing: 'border-box',
          position: 'absolute',
        }}
      >
        <div style={{ fontFamily: SANS, fontSize: 15, letterSpacing: 1.3, color: DIM, fontWeight: 700, padding: '4px 12px 14px' }}>SHIP IT</div>
        <div style={{ position: 'relative', height: ROW_Y[5] + 62 }}>
          {MENU.map(function (m, i) {
            const p = spring({ frame: frame - (4 + i * 4), fps: 30, config: { damping: 13, stiffness: 240, mass: 1 } });
            const on = i === hover;
            return (
              <div
                key={m[0]}
                style={{
                  position: 'absolute',
                  left: 0,
                  top: ROW_Y[i],
                  width: 624,
                  height: 62,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 18,
                  padding: '0 16px',
                  borderRadius: 13,
                  boxSizing: 'border-box',
                  background: on ? 'rgba(111,71,245,0.18)' : 'transparent',
                  border: '1px solid ' + (on ? 'rgba(111,71,245,0.4)' : 'rgba(255,255,255,0)'),
                  opacity: Math.max(0, p),
                  transform: 'translateY(' + (1 - Math.max(0, p)) * 18 + 'px) scale(' + (0.9 + Math.max(0, Math.min(1, p)) * 0.1) + ')',
                }}
              >
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke={on ? BRAND_400 : MUTED} strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
                  <path d={m[1]} />
                </svg>
                <span style={{ fontFamily: SANS, fontSize: 23, color: on ? FG : '#cbd5e1', fontWeight: on ? 600 : 500 }}>{m[0]}</span>
                {i === 5 ? (
                  <span style={{ marginLeft: 'auto', fontFamily: MONO, fontSize: 15, color: DIM }}>⌘C</span>
                ) : null}
                {i === hover ? <CursorAt dx={cx} dy={cy} frame={frame} clickAt={i === 5 ? CLICK : -1} opacity={cOp} /> : null}
              </div>
            );
          })}
        </div>
      </div>
    </Canvas>
  );
}

