/* SCENE 29 — handoff · the command block, and a real confirm (78f)
   The menu chose Copy SSH command, so this is what it produced: an actual
   command, not a picture of one.
   2-13   the cursor arrives, mounted inside the Copy button
   18     click
   19     CONSEQUENCE: Copy becomes Copied, in green, with a check — the beat
          that motivates the cut to the ident
   26-34  the cursor leaves */

const CMD = 'ssh root@web-prod-01.nxeon.cloud';
const CLICK = 18;

export default function Scene_handoff_copy() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const s = settle(frame, 0, fps);
  const scale = 0.94 + s * 0.06;
  const op = interpolate(frame, [0, 8], [0, 1], { ...CL, easing: OUT3 });

  const cdx = ballistic(frame, 2, -820, 0);
  const cdy = ballistic(frame, 2, 300, 0);
  const cOp = interpolate(frame, [26, 34], [1, 0], CL);

  const copied = frame >= CLICK + 1;
  const flash = interpolate(frame, [CLICK, CLICK + 14], [1, 0], { ...CL, easing: OUT3 });

  return (
    <Canvas>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div
          style={{
            width: 1180,
            borderRadius: 24,
            border: '1px solid rgba(255,255,255,0.1)',
            background: 'linear-gradient(180deg, rgba(13,21,38,0.98), rgba(6,10,20,0.98))',
            boxShadow: '0 60px 150px -50px rgba(0,0,0,0.95)',
            padding: '38px 40px 40px',
            transform: 'scale(' + scale + ')',
            opacity: op,
            boxSizing: 'border-box',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 18 }}>
            <Mark size={30} opacity={1} />
            <span style={{ fontFamily: SANS, fontSize: 27, color: FG, fontWeight: 600 }}>Connect to your server</span>
            <span style={{ marginLeft: 'auto' }}>
              <Pill text="99.9% uptime SLA" tone="idle" />
            </span>
          </div>

          <div
            style={{
              marginTop: 26,
              borderRadius: 16,
              border: '1px solid ' + (copied ? 'rgba(52,211,153,0.36)' : 'rgba(255,255,255,0.09)'),
              background: 'rgba(0,0,0,0.42)',
              padding: '26px 28px',
              display: 'flex',
              alignItems: 'center',
              gap: 24,
              boxShadow: copied ? '0 0 0 ' + flash * 8 + 'px rgba(52,211,153,' + flash * 0.18 + ')' : 'none',
            }}
          >
            <span style={{ fontFamily: MONO, fontSize: 20, color: GREEN }}>$</span>
            <span style={{ fontFamily: MONO, fontSize: 32, color: FG, letterSpacing: -0.6, whiteSpace: 'pre' }}>{CMD}</span>
            <div
              style={{
                position: 'relative',
                marginLeft: 'auto',
                display: 'inline-flex',
                alignItems: 'center',
                gap: 11,
                padding: '14px 26px',
                borderRadius: 12,
                background: copied ? 'rgba(52,211,153,0.14)' : GRAD,
                border: '1px solid ' + (copied ? 'rgba(52,211,153,0.4)' : 'rgba(255,255,255,0)'),
                color: copied ? GREEN : FG,
                fontFamily: SANS,
                fontSize: 20,
                fontWeight: 650,
                transform: 'scale(' + (frame >= CLICK && frame < CLICK + 6 ? 0.96 : 1) + ')',
                whiteSpace: 'nowrap',
              }}
            >
              {copied ? (
                <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke={GREEN} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M4 12.5 L9.5 18 L20 6" />
                </svg>
              ) : null}
              {copied ? 'Copied' : 'Copy'}
              <CursorAt dx={cdx} dy={cdy} frame={frame} clickAt={CLICK} opacity={cOp} />
            </div>
          </div>

          <div style={{ marginTop: 22, fontFamily: SANS, fontSize: 19, color: MUTED }}>
            Full root access on every plan · free migration in · cancel anytime
          </div>
        </div>
      </div>
    </Canvas>
  );
}
