/* SCENE 30 — brand-ident · the callback (92f)
   The same mark, the same wordmark, at the same size and the same place it
   sat in the cold open — the film closes the loop before it signs off.
   0-14   the wordmark returns, letters filling left to right (the exact
          inverse of the drain in scene 02)
   22-46  the offer tracks in beneath it, letter-spacing closing up
   50-72  the CTA line follows */

export default function Scene_ident_callback() {
  const frame = useCurrentFrame();

  // inverse of the scene-02 drain: letters fill left to right
  const fill = function (i) {
    return interpolate(frame, [i * 2, i * 2 + 8], [0, 1], CL);
  };

  const t1 = interpolate(frame, [22, 46], [0, 1], { ...CL, easing: OUT4 });
  const t2 = interpolate(frame, [50, 72], [0, 1], { ...CL, easing: OUT4 });

  return (
    <Canvas>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <Wordmark size={92} tracking={7} color={FG} letterOpacity={fill} />

          <div
            style={{
              marginTop: 46,
              fontFamily: SANS,
              fontSize: 34,
              fontWeight: 500,
              color: '#cbd5e1',
              letterSpacing: interpolate(t1, [0, 1], [14, 0.4]),
              opacity: t1,
              whiteSpace: 'nowrap',
            }}
          >
            First month free on shared hosting.
          </div>

          <div
            style={{
              marginTop: 20,
              fontFamily: SANS,
              fontSize: 30,
              fontWeight: 500,
              letterSpacing: interpolate(t2, [0, 1], [12, 0.4]),
              opacity: t2,
              whiteSpace: 'nowrap',
              background: GRAD_TEXT,
              WebkitBackgroundClip: 'text',
              backgroundClip: 'text',
              color: 'transparent',
            }}
          >
            Deploy your server at nxeon.cloud today.
          </div>
        </div>
      </div>
    </Canvas>
  );
}
