cat > 31-ident-final.tsx <<'EOF'

/* SCENE 31 — brand-ident · the sign-off (110f)
   0-18   the mark pops in with an overshoot
   16-34  the wordmark WIPES on left to right (a clip, not a fade)
   38-52  the rule and the strapline settle
   52-110 a long, still hold to close. Nothing moves at the end of a film. */

export default function Scene_ident_final() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const pop = spring({ frame: frame, fps: fps, config: { damping: 11, stiffness: 210, mass: 1 } });
  const markScale = 0.55 + pop * 0.45;
  const markOp = interpolate(frame, [0, 7], [0, 1], CL);

  const wipe = interpolate(frame, [16, 34], [0, 100], { ...CL, easing: OUT4 });
  const ruleP = interpolate(frame, [38, 52], [0, 1], { ...CL, easing: OUT4 });
  const lineP = interpolate(frame, [44, 60], [0, 1], { ...CL, easing: OUT4 });

  return (
    <Canvas>
      <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 34 }}>
            <div style={{ transform: 'scale(' + markScale + ')', opacity: markOp }}>
              <Mark size={116} opacity={1} />
            </div>
            <div style={{ overflow: 'hidden', clipPath: 'inset(0 ' + (100 - wipe) + '% 0 0)' }}>
              <Wordmark size={116} tracking={9} color={FG} />
            </div>
          </div>

          <div
            style={{
              width: interpolate(ruleP, [0, 1], [0, 620]),
              height: 1,
              background: 'linear-gradient(90deg, rgba(59,130,246,0), rgba(138,112,251,0.85), rgba(59,130,246,0))',
              marginTop: 44,
            }}
          />

          <div
            style={{
              marginTop: 30,
              fontFamily: SANS,
              fontSize: 27,
              fontWeight: 500,
              color: MUTED,
              letterSpacing: 1.6,
              opacity: lineP,
              whiteSpace: 'nowrap',
            }}
          >
            Your business, online in 47 seconds.
          </div>

          <div style={{ marginTop: 26, opacity: lineP }}>
            <Pill text="nxeon.cloud" tone="brand" mono />
          </div>
        </div>
      </div>
    </Canvas>
  );
}
