import fs from 'node:fs';
import path from 'node:path';
import { renderSceneHtml } from './render.mjs';
const HERE = path.dirname(new URL(import.meta.url).pathname);
const scene = path.resolve(process.argv[2]);
const frames = process.argv[3].split(',').map(Number);
const sel = process.argv[4];
const { chromium } = await import('playwright');
const b = await chromium.launch({ args: ['--no-sandbox'] });
const p = await b.newPage({ viewport: { width: 1920, height: 1080 } });
for (const f of frames) {
  const html = await renderSceneHtml(scene, f, 40);
  const tmp = path.join(HERE, '_m.html');
  fs.writeFileSync(tmp, html);
  await p.goto('file://' + tmp);
  const r = await p.evaluate((s) => {
    const el = document.querySelector(s);
    if (!el) return null;
    const b = el.getBoundingClientRect();
    return { w: Math.round(b.width), h: Math.round(b.height), x: Math.round(b.x), y: Math.round(b.y), text: el.innerText.slice(0, 40) };
  }, sel);
  console.log('frame ' + String(f).padStart(3) + '  ' + JSON.stringify(r));
}
await b.close();
