import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
const ROOT = path.dirname(new URL(import.meta.url).pathname);
const P = '084d3e8c-2ec8-4a9b-ac1a-96ef5738db08';
const tl = JSON.parse(fs.readFileSync(path.join(ROOT, 'timeline.json'), 'utf8'));
const out = [];
for (const s of tl) {
  const r = execFileSync('baz', [
    'scenes', 'create',
    '--name', s.name,
    '--file', path.join(ROOT, 'scenes', s.file),
    '--duration', String(s.duration),
    '--track', '0',
    '--start', String(s.start),
    '--project-id', P, '--json',
  ], { encoding: 'utf8', maxBuffer: 1 << 26 });
  const j = JSON.parse(r);
  out.push({ file: s.file, sceneId: j.sceneId, track: j.track, start: j.propsStart, duration: j.duration, err: j.compilationError, warn: j.warnings, pushed: j.trackAutoPushed });
  console.log(
    (j.compilationError ? 'ERR  ' : 'ok   ') + s.file.padEnd(30) +
    ' t' + j.track + ' @' + String(j.propsStart).padStart(4) + ' +' + String(j.duration).padStart(3) +
    (j.trackAutoPushed ? '  AUTOPUSHED' : '') +
    (j.compilationError ? '  ' + JSON.stringify(j.compilationError).slice(0, 200) : '')
  );
}
fs.writeFileSync(path.join(ROOT, 'pushed.json'), JSON.stringify(out, null, 2));
